      "path": "lib/artifact.js",
      "content": "/**\n * Trellis Artifact Update Tool (`trellis_artifact_update`).\n *\n * Provides a secure, controlled channel for models to write planning and verification\n * markdown documents (PRD, design, review, check, etc.) directly into the active\n * task's directory (.trellis/tasks/<slug>/).\n *\n * Enforces strict sandbox boundaries:\n *  - Only pre-whitelisted standard workflow artifact file names are permitted.\n *  - Path traversal (..) or subdirectories are strictly forbidden.\n *  - Modifying project source code or files outside the task directory is physically impossible.\n */\n\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport path from 'node:path'\nimport { normalizePath, matchAllowlist } from './resolve.js'\nimport { findActiveTaskSlug } from './task.js'\nimport { SLUG_CHARSET } from './archive.js'\n\n/**\n * Standard artifact file names allowed across feat, issue, and refactor workflows.\n */\nexport const ALLOWED_ARTIFACTS = new Set([\n  // feat workflow artifacts\n  'prd.md',\n  'design.md',\n  'design-review.md',\n  'implement.md',\n  'review.md',\n  'check.md',\n  // issue workflow artifacts\n  'report.md',\n  'analysis.md',\n  'fix-note.md',\n  // refactor workflow artifacts\n  'scan.md',\n  'refactor-design.md',\n  'apply-notes.md',\n  'checklist.yaml',\n])\n\n/**\n * Assert that the target artifact path is strictly within the specified task directory.\n * @param {string} root normalized project root\n * @param {string} slug task slug\n * @param {string} artifact base file name\n * @returns {string} resolved target absolute path\n */\nexport function assertSafeArtifactPath(root, slug, artifact) {\n  if (typeof slug !== 'string' || !slug.trim()) {\n    throw new Error('任务 slug 不能为空')\n  }\n  const safeSlug = slug.trim()\n  if (!SLUG_CHARSET.test(safeSlug)) {\n    throw new Error(`非法的任务 slug：包含路径分隔符或越权字符 (${safeSlug})`)\n  }\n\n  // Belt-and-suspenders: the slug must resolve to a DIRECT child of the tasks\n  // dir (rejects `.`, `..`, and any dotted/pathological segment that slips past\n  // the charset guard).\n  const tasksDir = path.join(root, '.trellis', 'tasks')\n  const taskDir = path.join(tasksDir, safeSlug)\n  const taskRel = path.relative(tasksDir, taskDir)\n  if (taskRel !== safeSlug || taskRel.startsWith('..') || path.isAbsolute(taskRel)) {\n    throw new Error(`非法的任务 slug：路径越权 (${safeSlug})`)\n  }\n\n  if (typeof artifact !== 'string' || !artifact.trim()) {\n    throw new Error('artifact 名称不能为空')\n  }\n  const name = artifact.trim()\n  if (!ALLOWED_ARTIFACTS.has(name)) {\n    throw new Error(\n      `不允许更新非标准产物文件 \"${name}\"；合法产物仅限：${[...ALLOWED_ARTIFACTS].join(', ')}`,\n    )\n  }\n  if (name.includes('/') || name.includes('\\\\') || name.includes('..')) {\n    throw new Error(`非法的文件名包含路径穿越或分隔符: \"${name}\"`)\n  }\n\n  const targetPath = path.join(taskDir, name)\n\n  // Ensure targetPath is strictly inside taskDir\n  const rel = path.relative(taskDir, targetPath)\n  if (rel.startsWith('..') || path.isAbsolute(rel) || rel !== name) {\n    throw new Error(`路径越权：产物写入必须局限在当前任务目录内 (${name})`)\n  }\n\n  return targetPath\n}\n\n/**\n * Update a task artifact file end-to-end.\n * @param {import('@deepseek-ai/dsh-fs').FileSystem} dshFs\n * @param {string} root project root\n * @param {object} args { artifact, content, slug?, cwd? }\n * @param {object} [exec] { signal?, sessionId? }\n * @param {object} [sandboxPolicy]\n * @returns {Promise<{ ok: true, slug: string, artifact: string, filePath: string, bytesWritten: number } | { ok: false, error: string }>}\n */\nexport async function updateTaskArtifact(dshFs, root, args, exec = {}, sandboxPolicy) {\n  let slug = args.slug && typeof args.slug === 'string' ? args.slug.trim() : undefined\n  if (!slug) {\n    const sessionId =\n      typeof exec.sessionId === 'string'\n        ? exec.sessionId\n        : exec.agent && exec.agent.session && typeof exec.agent.session.id === 'string'\n          ? exec.agent.session.id\n          : undefined\n    slug = await findActiveTaskSlug(dshFs, root, sessionId)\n    if (!slug) {\n      return { ok: false, error: '未指定 slug 且当前会话未绑定任何活动任务' }\n    }\n  }\n\n  const content = typeof args.content === 'string' ? args.content : ''\n  if (!content.trim()) {\n    return { ok: false, error: 'content 不能为空' }\n  }\n\n  let targetPath\n  try {\n    targetPath = assertSafeArtifactPath(root, slug, args.artifact)\n  } catch (err) {\n    return { ok: false, error: err.message }\n  }\n\n  const taskJsonPath = path.join(root, '.trellis', 'tasks', slug, 'task.json')\n  const taskJsonTarget = await dshFs.resolve(taskJsonPath)\n  const stat = await dshFs.stat(taskJsonTarget)\n  if (!stat) {\n    return { ok: false, error: `任务目录不存在：.trellis/tasks/${slug}/` }\n  }\n\n  const resolvedTarget = await dshFs.resolve(targetPath)\n  await dshFs.writeText(resolvedTarget, content, undefined, exec.signal, sandboxPolicy)\n\n  return {\n    ok: true,\n    slug,\n    artifact: args.artifact.trim(),\n    filePath: `.trellis/tasks/${slug}/${args.artifact.trim()}`,\n    bytesWritten: Buffer.byteLength(content, 'utf8'),\n  }\n}\n\n/**\n * Create the defineTool instance for trellis_artifact_update.\n * @param {object} deps { ctx, effectiveConfig }\n */\nexport function createArtifactUpdateTool({ ctx, effectiveConfig }) {\n  return defineTool({\n    name: 'trellis_artifact_update',\n    description:\n      '更新当前 Trellis 任务的阶段交付文档（PRD、设计方案、实现备忘、验收报告等）。受安全沙箱保护，仅允许写入任务目录内的合法 Markdown 产物，严禁修改任何项目源代码。',\n    parameters: {\n      artifact: {\n        type: 'string',\n        description: `产物文件名。允许项：${[...ALLOWED_ARTIFACTS].join(' | ')}`,\n      },\n      content: {\n        type: 'string',\n        description: '产物完整 UTF-8 Markdown 正文内容。',\n      },\n      slug: {\n        type: 'string',\n        description: '可选 explicit task slug；默认绑定当前会话的活动任务。',\n      },\n      cwd: {\n        type: 'string',\n        description: '可选项目根目录绝对路径。默认使用当前会话 cwd。',\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          ok: { type: 'boolean' },\n          error: { oneOf: [{ type: 'string' }, { type: 'null' }] },\n          slug: { oneOf: [{ type: 'string' }, { type: 'null' }] },\n          artifact: { oneOf: [{ type: 'string' }, { type: 'null' }] },\n          filePath: { oneOf: [{ type: 'string' }, { type: 'null' }] },\n          bytesWritten: { oneOf: [{ type: 'number' }, { type: 'null' }] },\n        },\n      },\n      render(args, value) {\n        return [{ type: 'text', text: JSON.stringify(value, null, 2) }]\n      },\n    },\n    async execute(args, exec) {\n      const cwd = normalizePath(\n        args.cwd || (exec.agent && exec.agent.session && exec.agent.session.header && exec.agent.session.header.cwd),\n      )\n      const root = matchAllowlist(cwd, effectiveConfig.get().allowlist)\n      if (!root) {\n        return {\n          ok: false,\n          error: '项目不在 allowlist 内；请先在 Web 设置或配置里把项目根加入 trellis-workflow.allowlist',\n          slug: null,\n          artifact: null,\n          filePath: null,\n          bytesWritten: null,\n        }\n      }\n\n      const policy = ctx.fs.sandboxMode === void 0 ? void 0 : ctx.get('sandboxPolicy')\n      const sandboxPolicy = policy\n        ? policy.resolve({ ...(exec.agent === void 0 ? {} : { session: exec.agent.session }) })\n        : void 0\n\n      const result = await updateTaskArtifact(ctx.fs, root, args, exec, sandboxPolicy)\n      if (!result.ok) {\n        return {\n          ok: false,\n          error: result.error,\n          slug: null,\n          artifact: null,\n          filePath: null,\n          bytesWritten: null,\n        }\n      }\n      return {\n        ok: true,\n        error: null,\n        slug: result.slug,\n        artifact: result.artifact,\n        filePath: result.filePath,\n        bytesWritten: result.bytesWritten,\n      }\n    },\n  })\n}\n"
    },
    {
      "path": "lib/skills.js",
      "content": "/**\n * Bundled trellis skill provisioning for the trellis workflow trigger.\n *\n * The 15 `trellis-*` skills ship with the package as the authoritative copy,\n * but are NOT registered through `ctx.skills` anymore. Instead the per-turn\n * breadcrumb injection (see lib/index.js) detects whether the project's\n * `.agents/skills/` already carries them — the harness's built-in\n * `dsh-skill-filesystem` provider discovers skills from that project root —\n * and copies the missing skill directories (plus the shared `_templates/`)\n * from the package on first use. Projects with their own copies are left\n * untouched (presence check → skip).\n */\n\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport { assertPolicyAllowsWrite } from './archive.js'\n\nconst here = path.dirname(fileURLToPath(import.meta.url))\n/** Absolute directory of the packaged `skills/` folder (the copy source). */\nexport const skillsRoot = path.resolve(here, '..', 'skills')\n\nlet packageVersion = '0.0.0'\ntry {\n  const pkgPath = path.resolve(here, '..', 'package.json')\n  const raw = fs.readFileSync(pkgPath, 'utf8')\n  const parsed = JSON.parse(raw)\n  if (typeof parsed.version === 'string' && parsed.version) {\n    packageVersion = parsed.version\n  }\n} catch {\n  /* fallback */\n}\nexport const PACKAGE_VERSION = packageVersion\nexport const VERSION_FILE_NAME = '.trellis-version'\n\n/**\n * Project-level template files that are deprecated in this release and must be\n * pruned from existing projects when the plugin runs there (self-healing).\n *\n * Two locations mirror the two copy/init paths:\n *  - `.agents/skills/_templates/...` — copied by ensureProjectSkills below;\n *  - `.trellis/templates/...`        — initialized by createTaskRecord on first\n *    use of a work type (lib/task.js).\n *\n * The list is deliberately hard-coded and relative: pruning NEVER touches any\n * `tasks/` directory (historical artifacts stay intact) and never scans\n * user content — only these exact relative paths are unlinked when present.\n */\nexport const DEPRECATED_PROJECT_TEMPLATES = [\n  path.join('.agents', 'skills', '_templates', 'feat', 'implement.md'),\n  path.join('.agents', 'skills', '_templates', 'refactor', 'checklist.yaml'),\n  path.join('.trellis', 'templates', 'feat', 'implement.md'),\n  path.join('.trellis', 'templates', 'refactor', 'checklist.yaml'),\n]\n\n/**\n * Prune deprecated project template files (self-healing migration).\n *\n * The harness fs (ctx.fs) has no delete primitive, so this uses node:fs\n * unlink — a tightly-bounded exception like the archive move: paths are\n * hard-coded relative, validated to sit inside the project root, and fenced by\n * `assertPolicyAllowsWrite` (fail-closed on read-only / outside-workspace\n * policies). Failures never throw into the turn: a prune that cannot run\n * (e.g. read-only sandbox) is skipped silently so breadcrumb injection keeps\n * working; the next writable turn retries.\n * @param {import('@deepseek-ai/dsh-fs').FileSystem} dshFs ctx.fs.\n * @param {string} root normalized project root (allowlist-matched).\n * @param {object} [opts] { sandboxPolicy? } resolved per-call policy.\n * @returns {{ pruned: string[], skipped: string[] }}\n */\nexport async function pruneDeprecatedProjectTemplates(dshFs, root, { sandboxPolicy } = {}) {\n  const pruned = []\n  const skipped = []\n  for (const rel of DEPRECATED_PROJECT_TEMPLATES) {\n    const abs = path.join(root, rel)\n    try {\n      const target = await dshFs.resolve(abs)\n      const info = await dshFs.stat(target)\n      if (!info) continue\n      // Policy fence for the node:fs mutation (fail-closed, mirrors archive).\n      try {\n        assertPolicyAllowsWrite(sandboxPolicy, rel.replace(/\\\\/g, '/'), root)\n      } catch (err) {\n        skipped.push(rel)\n        continue\n      }\n      // unlink takes the real path string, not the resolved fs target object.\n      fs.unlinkSync(abs)\n      pruned.push(rel)\n      console.log(`[trellis] pruned deprecated template: ${rel}`)\n    } catch {\n      /* absent or unreadable — nothing to prune */\n    }\n  }\n  return { pruned, skipped }\n}\n\n/** Bundle id → subdirectory name under skillsRoot (the copy units). */\nconst SKILL_DIRS = [\n  'trellis-start',\n  'trellis-brainstorm',\n  'trellis-before-dev',\n  'trellis-check',\n  'trellis-update-spec',\n  'trellis-finish-work',\n  'trellis-continue',\n  'trellis-break-loop',\n  'trellis-channel',\n  'trellis-meta',\n  'trellis-session-insight',\n  'trellis-spec-bootstrap',\n  'trellis-feat',\n  'trellis-issue',\n  'trellis-refactor',\n]\n\n/**\n * Recursively collect relative file paths under a source directory (node fs —\n * the source is the package's own bundled assets, not the project).\n * @param {string} dir absolute source directory.\n * @param {string} [prefix] accumulated relative prefix.\n * @returns {string[]} relative file paths (forward-slash free; platform sep).\n */\nfunction collectFiles(dir, prefix = '') {\n  const out = []\n  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {\n    const rel = prefix ? path.join(prefix, entry.name) : entry.name\n    if (entry.isDirectory()) out.push(...collectFiles(path.join(dir, entry.name), rel))\n    else if (entry.isFile()) out.push(rel)\n  }\n  return out\n}\n\n/**\n * Ensure the project's `.agents/skills/` carries every bundled trellis skill.\n *\n * Checks the `.trellis-version` marker in the project's `.agents/skills/`:\n *  - Same version: presence check skips existing skills (zero write overhead).\n *  - New version / upgrade / force: overwrites official `SKILL_DIRS` and templates\n *    with the package's latest version (self-updating).\n * Custom skills created by users in `.agents/skills/` remain untouched.\n *\n * @param {import('@deepseek-ai/dsh-fs').FileSystem} dshFs ctx.fs.\n * @param {string} root normalized project root (allowlist-matched).\n * @param {object} [opts] { signal?, sandboxPolicy?, force? } forwarded to writes.\n * @returns {Promise<{ copied: string[], updated: string[], present: string[], version: string }>}\n */\nexport async function ensureProjectSkills(dshFs, root, { signal, sandboxPolicy, force = false } = {}) {\n  const targetRoot = path.join(root, '.agents', 'skills')\n  const copied = []\n  const updated = []\n  const present = []\n\n  // Check version record in project\n  let installedVersion = null\n  try {\n    const versionTarget = await dshFs.resolve(path.join(targetRoot, VERSION_FILE_NAME))\n    const info = await dshFs.stat(versionTarget)\n    if (info) {\n      const raw = await dshFs.readText(versionTarget, signal)\n      if (typeof raw === 'string') installedVersion = raw.trim()\n    }\n  } catch {\n    /* absent or unreadable */\n  }\n\n  const isUpgrade = force || (installedVersion !== PACKAGE_VERSION)\n\n  // One listing decides presence; absent dir → empty (nothing present yet).\n  let existing = new Set()\n  try {\n    const dirTarget = await dshFs.resolve(targetRoot)\n    const entries = await dshFs.listDir(dirTarget)\n    existing = new Set(entries.map((entry) => entry.name))\n  } catch {\n    /* .agents/skills absent — treat as empty */\n  }\n\n  // 1. Skill directories\n  for (const id of SKILL_DIRS) {\n    const srcDir = path.join(skillsRoot, id)\n    if (!fs.existsSync(srcDir)) continue\n    const alreadyExists = existing.has(id)\n\n    if (alreadyExists && !isUpgrade) {\n      present.push(id)\n      continue\n    }\n\n    for (const rel of collectFiles(srcDir)) {\n      const t = await dshFs.resolve(path.join(targetRoot, id, rel))\n      const content = fs.readFileSync(path.join(srcDir, rel), 'utf8')\n      await dshFs.writeText(t, content, undefined, signal, sandboxPolicy)\n    }\n\n    if (alreadyExists) {\n      updated.push(id)\n    } else {\n      copied.push(id)\n    }\n  }\n\n  // 2. Shared artifact templates (`_templates/`), copied file-by-file.\n  const tplSrc = path